CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_attempts(id uuid PRIMARY KEY,access_hash text NOT NULL,session_id text UNIQUE,amount_cents integer NOT NULL CHECK(amount_cents>0),provider text NOT NULL,status text NOT NULL DEFAULT 'CREATED',customer_id uuid REFERENCES customers(id),stripe_customer text,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(id uuid PRIMARY KEY,customer_id uuid UNIQUE NOT NULL REFERENCES customers(id),payment_id uuid UNIQUE NOT NULL REFERENCES payment_attempts(id),os_reference text UNIQUE NOT NULL,status text NOT NULL,activated_at timestamptz NOT NULL DEFAULT now(),renews_at timestamptz NOT NULL,renewal_cents integer NOT NULL,renewal_status text NOT NULL DEFAULT 'SETUP_PENDING',schedule_id text UNIQUE,subscription_id text UNIQUE,cancel_at_period_end boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS desks(id uuid PRIMARY KEY,membership_id uuid UNIQUE NOT NULL REFERENCES memberships(id),customer_id uuid UNIQUE NOT NULL REFERENCES customers(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflows(id uuid PRIMARY KEY,desk_id uuid NOT NULL REFERENCES desks(id),module text NOT NULL,state text NOT NULL,version integer NOT NULL DEFAULT 1,source text NOT NULL,rule_version text NOT NULL,UNIQUE(desk_id,module));
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY,desk_id uuid REFERENCES desks(id),actor text NOT NULL,kind text NOT NULL,previous_state text,new_state text,source text,rule_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_events(id text PRIMARY KEY,type text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES customers(id),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_tokens(id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES customers(id),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE IF NOT EXISTS customer_items(id uuid PRIMARY KEY,desk_id uuid NOT NULL REFERENCES desks(id),module text NOT NULL,request_key text NOT NULL,value jsonb NOT NULL,status text NOT NULL DEFAULT 'RECEIVED',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(desk_id,request_key));
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY,desk_id uuid NOT NULL REFERENCES desks(id),module text NOT NULL,label text NOT NULL,reference text NOT NULL,version integer NOT NULL DEFAULT 1,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS obligations(id uuid PRIMARY KEY,desk_id uuid NOT NULL REFERENCES desks(id),title text NOT NULL,due_at date,status text NOT NULL DEFAULT 'FACTS_REQUIRED',source text NOT NULL,rule_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(desk_id,title));
CREATE TABLE IF NOT EXISTS analytics(id text PRIMARY KEY,name text NOT NULL,visitor text,customer_id uuid REFERENCES customers(id),dimensions jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economics(id uuid PRIMARY KEY,payment_id uuid UNIQUE REFERENCES payment_attempts(id),gross_cents integer NOT NULL,discount_cents integer NOT NULL DEFAULT 0,payment_fee_cents integer,financing_mdr_cents integer,provider_expense_cents integer,software_cost_cents integer,support_cost_cents integer,refund_cents integer,partner_payout_cents integer,cac_cents integer,channel text NOT NULL DEFAULT 'unknown');
CREATE TABLE IF NOT EXISTS referrals(id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES customers(id),code text UNIQUE NOT NULL,converted_payment_id uuid UNIQUE REFERENCES payment_attempts(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(bucket text PRIMARY KEY,hits integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS audit_desk_date ON audit_events(desk_id,created_at DESC);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS authorizations(id uuid PRIMARY KEY,workflow_id uuid NOT NULL REFERENCES workflows(id),workflow_version integer NOT NULL,customer_id uuid NOT NULL REFERENCES customers(id),document_hash text NOT NULL,description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workflow_id,workflow_version));
ALTER TABLE payment_attempts ADD COLUMN IF NOT EXISTS visitor text;
ALTER TABLE payment_attempts ADD COLUMN IF NOT EXISTS channel text NOT NULL DEFAULT 'unknown';
ALTER TABLE payment_attempts ADD COLUMN IF NOT EXISTS referral_code text;
